/* Portable C89/C99 spatial-variation, curved shoreline, prop-underlay & cast-shadow resolver */
static uint8_t hearth_is_solid_caster(uint8_t t) {
    return (t == T_WALL_WOOD || t == T_WALL_WINDOW || t == T_WALL_DOOR ||
            t == T_WINDMILL_WALL || t == T_WINDMILL_DOOR || t == T_CLIFF_WALL ||
            t == T_INTERIOR_WALL || t == T_HOLLOW_OAK) ? 1u : 0u;
}

static uint8_t hearth_is_water_like(uint8_t t) {
    return (t == T_WATER || t == T_FORD || t == T_RAPIDS || t == T_WORLD_OCEAN || t == T_WORLD_SHALLOW) ? 1u : 0u;
}

static uint8_t hearth_is_shallow_water(uint8_t t) {
    return (t == T_WORLD_SHALLOW || t == T_WORLD_CORAL) ? 1u : 0u;
}

static uint8_t hearth_is_grass_like(uint8_t t) {
    return (t == T_GRASS || t == T_GRASS_ALT || t == T_FLOWERS ||
            t == T_TALL_GRASS || t == T_AUTUMN_GRASS) ? 1u : 0u;
}

/* Infer dominant walkable ground underneath a prop (majority vote eliminates mismatched boxes!) */
static uint8_t hearth_infer_prop_ground(uint8_t tn, uint8_t ts, uint8_t tw, uint8_t te) {
    uint8_t wood = 0u, cob = 0u, pier = 0u, aut = 0u, dirt = 0u, sand = 0u, grass = 0u;
    uint8_t best = 0u, best_cnt;
    if (tn == T_WOOD_FLOOR || tn == T_HEARTH_RUG) wood++;
    if (ts == T_WOOD_FLOOR || ts == T_HEARTH_RUG) wood++;
    if (tw == T_WOOD_FLOOR || tw == T_HEARTH_RUG) wood++;
    if (te == T_WOOD_FLOOR || te == T_HEARTH_RUG) wood++;
    if (wood >= 1u) return 5u; /* Cozy Cottage / Shop Wood Floor */
    if (tn == T_GRASS || tn == T_GRASS_ALT || tn == T_FLOWERS || tn == T_TALL_GRASS) grass++;
    if (ts == T_GRASS || ts == T_GRASS_ALT || ts == T_FLOWERS || ts == T_TALL_GRASS) grass++;
    if (tw == T_GRASS || tw == T_GRASS_ALT || tw == T_FLOWERS || tw == T_TALL_GRASS) grass++;
    if (te == T_GRASS || te == T_GRASS_ALT || te == T_FLOWERS || te == T_TALL_GRASS) grass++;
    if (tn == T_DOCK_PIER || tn == T_BRIDGE) pier++;
    if (ts == T_DOCK_PIER || ts == T_BRIDGE) pier++;
    if (tw == T_DOCK_PIER || tw == T_BRIDGE) pier++;
    if (te == T_DOCK_PIER || te == T_BRIDGE) pier++;
    if (tn == T_COBBLE || tn == T_ROCKY_PATH || tn == T_SHRINE_FLOOR || tn == T_SHRINE_RUNE) cob++;
    if (ts == T_COBBLE || ts == T_ROCKY_PATH || ts == T_SHRINE_FLOOR || ts == T_SHRINE_RUNE) cob++;
    if (tw == T_COBBLE || tw == T_ROCKY_PATH || tw == T_SHRINE_FLOOR || tw == T_SHRINE_RUNE) cob++;
    if (te == T_COBBLE || te == T_ROCKY_PATH || te == T_SHRINE_FLOOR || te == T_SHRINE_RUNE) cob++;
    if (tn == T_AUTUMN_GRASS) aut++;
    if (ts == T_AUTUMN_GRASS) aut++;
    if (tw == T_AUTUMN_GRASS) aut++;
    if (te == T_AUTUMN_GRASS) aut++;
    if (tn == T_WORLD_SAND || tn == T_WORLD_BEACH) sand++;
    if (ts == T_WORLD_SAND || ts == T_WORLD_BEACH) sand++;
    if (tw == T_WORLD_SAND || tw == T_WORLD_BEACH) sand++;
    if (te == T_WORLD_SAND || te == T_WORLD_BEACH) sand++;
    if (tn == T_DIRT) dirt++;
    if (ts == T_DIRT) dirt++;
    if (tw == T_DIRT) dirt++;
    if (te == T_DIRT) dirt++;
    best_cnt = grass;
    if (dirt > best_cnt || (dirt == best_cnt && dirt > 0u)) { best = 4u; best_cnt = dirt; }
    if (sand > best_cnt || (sand == best_cnt && sand > 0u)) { best = 6u; best_cnt = sand; }
    if (aut  > best_cnt || (aut  == best_cnt && aut  > 0u)) { best = 3u; best_cnt = aut;  }
    if (cob  > best_cnt || (cob  == best_cnt && cob  > 0u)) { best = 1u; best_cnt = cob;  }
    if (pier > best_cnt || (pier == best_cnt && pier > 0u)) { best = 2u; best_cnt = pier; }
    return best;
}

static uint8_t hearth_is_shore_land(uint8_t t, uint8_t is_world) {
    if (hearth_is_water_like(t) || t == T_WORLD_CORAL || t == T_DOCK_PIER) return 0u;
    if (!is_world && (t == T_BRIDGE || t == T_BRIDGE_RAIL_N || t == T_BRIDGE_RAIL_S)) return 0u;
    return 1u;
}

/* Compute local-zone directional flags: bit1=N-S vertical river, bit2=N-S bridge */
static uint8_t hearth_local_tile_flags(const uint8_t *bg1, uint16_t mx, uint16_t my, uint16_t mw, uint16_t mh) {
    uint8_t t = bg1[(uint32_t)my * mw + mx];
    uint8_t flags = 0u;
    uint16_t d;
    if (t == T_WATER || t == T_FORD || t == T_RAPIDS) {
        uint8_t land_w = 0u, land_e = 0u;
        uint8_t run_n = 0u, run_s = 0u;
        for (d = 1u; d <= 4u; d++) {
            if (my >= d) {
                uint8_t c = bg1[(uint32_t)(my - d) * mw + mx];
                if (hearth_is_water_like(c) || c == T_BRIDGE || c == T_BRIDGE_RAIL_N || c == T_BRIDGE_RAIL_S) run_n++;
                else break;
            }
        }
        for (d = 1u; d <= 4u; d++) {
            if (my + d < mh) {
                uint8_t c = bg1[(uint32_t)(my + d) * mw + mx];
                if (hearth_is_water_like(c) || c == T_BRIDGE || c == T_BRIDGE_RAIL_N || c == T_BRIDGE_RAIL_S) run_s++;
                else break;
            }
        }
        for (d = 1u; d <= 4u; d++) {
            if (mx >= d && hearth_is_shore_land(bg1[(uint32_t)my * mw + (mx - d)], 0u)) land_w = 1u;
            if (mx + d < mw && hearth_is_shore_land(bg1[(uint32_t)my * mw + (mx + d)], 0u)) land_e = 1u;
        }
        if (land_w && land_e && (uint8_t)(run_n + 1u + run_s) >= 5u) {
            flags |= 2u;
        }
    } else if (t == T_BRIDGE) {
        uint8_t tn = (my >= 1u) ? bg1[(uint32_t)(my - 1u) * mw + mx] : t;
        uint8_t ts = (my + 1u < mh) ? bg1[(uint32_t)(my + 1u) * mw + mx] : t;
        uint8_t wn = (my >= 1u && hearth_is_water_like(tn)) ? 1u : 0u;
        uint8_t ws = (my + 1u < mh && hearth_is_water_like(ts)) ? 1u : 0u;
        uint8_t rail_ns = (tn == T_BRIDGE_RAIL_N || tn == T_BRIDGE_RAIL_S || ts == T_BRIDGE_RAIL_N || ts == T_BRIDGE_RAIL_S) ? 1u : 0u;
        uint8_t road_ns = (tn == T_BRIDGE || ts == T_BRIDGE || tn == T_COBBLE || ts == T_COBBLE ||
                           tn == T_ROCKY_PATH || ts == T_ROCKY_PATH || tn == T_DIRT || ts == T_DIRT ||
                           tn == T_SHRINE_FLOOR || ts == T_SHRINE_FLOOR) ? 1u : 0u;
        uint8_t ww = 0u, we = 0u;
        if (!rail_ns) {
            if (ws && !wn) {
                flags |= 4u;
            } else if (!wn && ts == T_BRIDGE && my + 2u < mh && hearth_is_water_like(bg1[(uint32_t)(my + 2u) * mw + mx])) {
                flags |= 4u;
            } else if (road_ns) {
                for (d = 1u; d <= 4u; d++) {
                    if (mx >= d) {
                        uint8_t c = bg1[(uint32_t)my * mw + (mx - d)];
                        if (hearth_is_water_like(c)) { ww = 1u; break; }
                        if (c != T_BRIDGE) break;
                    }
                }
                for (d = 1u; d <= 4u; d++) {
                    if (mx + d < mw) {
                        uint8_t c = bg1[(uint32_t)my * mw + (mx + d)];
                        if (hearth_is_water_like(c)) { we = 1u; break; }
                        if (c != T_BRIDGE) break;
                    }
                }
                if ((ww || we) && ((!wn && !ws) || (ww && we))) {
                    flags |= 4u;
                }
            }
        }
    }
    return flags;
}

static uint8_t hearth_resolve_chrono_meta(uint8_t t, uint8_t ov,
                                          uint8_t tn, uint8_t ts, uint8_t tw, uint8_t te,
                                          uint8_t tnw, uint8_t tne, uint8_t tsw, uint8_t tse,
                                          uint16_t mx, uint16_t my, uint8_t flags) {
    uint8_t v = (uint8_t)(((mx * 3u + my * 5u) ^ (mx >> 1)) & 3u);
    uint8_t is_world = (uint8_t)(flags & 1u);
    uint8_t is_ns_river = (uint8_t)((flags & 2u) != 0u);
    uint8_t is_ns_bridge = (uint8_t)((flags & 4u) != 0u);
    uint8_t gnd;
    /* 1. Seamless Ground-Composited Props, Palms & Cozy Indoor Furniture */
    if (t == T_LANTERN_UNLIT) return (uint8_t)CM_LAMP_UNLIT;
    if (t == T_WORLD_PEAK) {
        if ((is_world && my < 40u) || tn == T_WORLD_SNOW || ts == T_WORLD_SNOW || tw == T_WORLD_SNOW || te == T_WORLD_SNOW)
            return (uint8_t)CM_PEAK_SNOW;
        if (is_world && mx < 68u && my >= 36u && my < 90u)
            return (uint8_t)CM_PEAK_VOLCANO;
        return T_WORLD_PEAK;
    }
    if (t == T_PALM_TREE) {
        uint8_t gc = (uint8_t)(hearth_is_grass_like(tn) + hearth_is_grass_like(ts) + hearth_is_grass_like(tw) + hearth_is_grass_like(te));
        uint8_t sc = (uint8_t)(((tn == T_WORLD_BEACH || tn == T_WORLD_SAND) ? 1u : 0u) +
                               ((ts == T_WORLD_BEACH || ts == T_WORLD_SAND) ? 1u : 0u) +
                               ((tw == T_WORLD_BEACH || tw == T_WORLD_SAND) ? 1u : 0u) +
                               ((te == T_WORLD_BEACH || te == T_WORLD_SAND) ? 1u : 0u));
        if (gc >= 1u && gc >= sc) return (uint8_t)CM_PALM_GRASS;
        return T_PALM_TREE;
    }
    if (t == T_LANTERN_POST || t == T_SIGNPOST || t == T_FLOWER_BED || t == T_BUSH || t == T_FENCE || t == T_BOULDER) {
        gnd = hearth_infer_prop_ground(tn, ts, tw, te);
        if (gnd == 5u) { /* Cottage / Shop Wood Floorboard Interior */
            if (t == T_LANTERN_POST) return (uint8_t)CM_LAMP_WOOD;
            if (t == T_FLOWER_BED)   return (uint8_t)CM_FLOWERBED_WOOD;
            if (t == T_BUSH)         return (uint8_t)CM_FLOWERBED_WOOD;
            if (t == T_FENCE)        return (uint8_t)CM_COUNTER_WOOD;
            if (t == T_SIGNPOST)     return (uint8_t)CM_LECTERN_WOOD;
        } else if (gnd == 1u) { /* Cobblestone / Stone Path / Shrine */
            if (t == T_LANTERN_POST) return (uint8_t)CM_LAMP_COBBLE;
            if (t == T_SIGNPOST)     return (uint8_t)CM_SIGN_COBBLE;
            if (t == T_FLOWER_BED)   return (uint8_t)CM_FLOWERBED_COBBLE;
            if (t == T_BUSH)         return (uint8_t)CM_BUSH_COBBLE;
            if (t == T_FENCE)        return (uint8_t)CM_FENCE_COBBLE;
            if (t == T_BOULDER)      return (uint8_t)CM_BOULDER_COBBLE;
        } else if (gnd == 2u) { /* Timber Pier */
            if (t == T_LANTERN_POST) return (uint8_t)CM_LAMP_PIER;
            if (t == T_SIGNPOST)     return (uint8_t)CM_SIGN_PIER;
            if (t == T_BOULDER)      return (uint8_t)CM_BOULDER_PIER;
        } else if (gnd == 3u) { /* Autumn Mountain */
            if (t == T_LANTERN_POST) return (uint8_t)CM_LAMP_AUTUMN;
            if (t == T_SIGNPOST)     return (uint8_t)CM_SIGN_AUTUMN;
            if (t == T_BOULDER)      return (uint8_t)CM_BOULDER_AUTUMN;
        } else if (gnd == 6u) { /* Coastal Beach / Desert Sand */
            if (t == T_LANTERN_POST) return (uint8_t)CM_LAMP_DIRT;
            if (t == T_SIGNPOST)     return (uint8_t)CM_SIGN_DIRT;
            if (t == T_BOULDER)      return (uint8_t)CM_BOULDER_SAND;
        } else if (gnd == 4u) { /* Dirt Road */
            if (t == T_LANTERN_POST) return (uint8_t)CM_LAMP_DIRT;
            if (t == T_SIGNPOST)     return (uint8_t)CM_SIGN_DIRT;
        }
        return t;
    }
    /* 1b. Cutaway Interior Wall Caps, 2-Tile Bed Footboard & Vertical N-S Bridges */
    if (t == T_INTERIOR_WALL && (ts == T_INTERIOR_WALL || ts == T_MTN_SKY || ts == T_WALL_WINDOW || ts == T_FIREPLACE || ts == T_WALL_WOOD)) {
        return (uint8_t)CM_INTERIOR_CAP;
    }
    if (t == T_BED_QUILT && tn == T_BED_QUILT) {
        return (uint8_t)CM_BED_FOOT;
    }
    if (!is_world && t == T_BRIDGE && is_ns_bridge) {
        return (uint8_t)CM_BRIDGE_NS;
    }
    /* 2. Timber Pier South Water-Piling Edge */
    if (t == T_DOCK_PIER && hearth_is_water_like(ts)) {
        return (uint8_t)CM_PIER_WATER_EDGE;
    }
    /* 3. Full 8-Neighbor Rounded Shorelines, Directional Rivers & Coastlines */
    if (t == T_WATER || t == T_FORD || t == T_RAPIDS || t == T_WORLD_SHALLOW || t == T_WORLD_OCEAN || t == T_WORLD_CORAL) {
        uint8_t ln  = hearth_is_shore_land(tn, is_world);
        uint8_t ls  = hearth_is_shore_land(ts, is_world);
        uint8_t lw  = hearth_is_shore_land(tw, is_world);
        uint8_t le  = hearth_is_shore_land(te, is_world);
        uint8_t lnw = hearth_is_shore_land(tnw, is_world);
        uint8_t lne = hearth_is_shore_land(tne, is_world);
        uint8_t lsw = hearth_is_shore_land(tsw, is_world);
        uint8_t lse = hearth_is_shore_land(tse, is_world);
        if (t == T_WORLD_OCEAN) {
            uint8_t sn  = hearth_is_shallow_water(tn);
            uint8_t ss  = hearth_is_shallow_water(ts);
            uint8_t sw  = hearth_is_shallow_water(tw);
            uint8_t se  = hearth_is_shallow_water(te);
            uint8_t snw = hearth_is_shallow_water(tnw);
            uint8_t sne = hearth_is_shallow_water(tne);
            uint8_t ssw = hearth_is_shallow_water(tsw);
            uint8_t sse = hearth_is_shallow_water(tse);
            if (ln || ls || lw || le) {
                if (ln && lw) return (uint8_t)CM_OCEAN_COAST_NW;
                if (ln && le) return (uint8_t)CM_OCEAN_COAST_NE;
                if (ls && lw) return (uint8_t)CM_OCEAN_COAST_SW;
                if (ls && le) return (uint8_t)CM_OCEAN_COAST_SE;
                if (ln) return (uint8_t)CM_OCEAN_COAST_N;
                if (ls) return (uint8_t)CM_OCEAN_COAST_S;
                if (lw) return (uint8_t)CM_OCEAN_COAST_W;
                if (le) return (uint8_t)CM_OCEAN_COAST_E;
            }
            if (sn || ss || sw || se) {
                if (sn && sw) return (uint8_t)CM_SHOAL_NW;
                if (sn && se) return (uint8_t)CM_SHOAL_NE;
                if (ss && sw) return (uint8_t)CM_SHOAL_SW;
                if (ss && se) return (uint8_t)CM_SHOAL_SE;
                if (sn) return (uint8_t)CM_SHOAL_N;
                if (ss) return (uint8_t)CM_SHOAL_S;
                if (sw) return (uint8_t)CM_SHOAL_W;
                if (se) return (uint8_t)CM_SHOAL_E;
            }
            if (lnw) return (uint8_t)CM_OCEAN_COAST_INW;
            if (lne) return (uint8_t)CM_OCEAN_COAST_INE;
            if (lsw) return (uint8_t)CM_OCEAN_COAST_ISW;
            if (lse) return (uint8_t)CM_OCEAN_COAST_ISE;
            if (snw) return (uint8_t)CM_SHOAL_INW;
            if (sne) return (uint8_t)CM_SHOAL_INE;
            if (ssw) return (uint8_t)CM_SHOAL_ISW;
            if (sse) return (uint8_t)CM_SHOAL_ISE;
            if (v & 1u) return (uint8_t)CM_OCEAN_V1;
            return t;
        }
        if (ln || ls || lw || le || lnw || lne || lsw || lse) {
            uint8_t use_sandy = (is_world || ((t == T_WORLD_SHALLOW || t == T_WORLD_CORAL) && !hearth_is_grass_like(tn) && !hearth_is_grass_like(ts) && !hearth_is_grass_like(tw) && !hearth_is_grass_like(te))) ? 1u : 0u;
            if (use_sandy) {
                if (ln && lw) return (uint8_t)CM_WORLD_COAST_NW;
                if (ln && le) return (uint8_t)CM_WORLD_COAST_NE;
                if (ls && lw) return (uint8_t)CM_WORLD_COAST_SW;
                if (ls && le) return (uint8_t)CM_WORLD_COAST_SE;
                if (ln) return (uint8_t)CM_WORLD_COAST_N;
                if (ls) return (uint8_t)CM_WORLD_COAST_S;
                if (lw) return (uint8_t)CM_WORLD_COAST_W;
                if (le) return (uint8_t)CM_WORLD_COAST_E;
                if (lnw) return (uint8_t)CM_WORLD_COAST_INW;
                if (lne) return (uint8_t)CM_WORLD_COAST_INE;
                if (lsw) return (uint8_t)CM_WORLD_COAST_ISW;
                if (lse) return (uint8_t)CM_WORLD_COAST_ISE;
            } else {
                if (ln && ls) return (uint8_t)CM_SHORE_NS;
                if (lw && le) return (uint8_t)CM_SHORE_WE;
                if (ln && lw) return (uint8_t)CM_SHORE_NW;
                if (ln && le) return (uint8_t)CM_SHORE_NE;
                if (ls && lw) return (uint8_t)CM_SHORE_SW;
                if (ls && le) return (uint8_t)CM_SHORE_SE;
                if (ln) return (uint8_t)CM_SHORE_N;
                if (ls) return (uint8_t)CM_SHORE_S;
                if (lw) return is_ns_river ? (uint8_t)CM_SHORE_V_W : (uint8_t)CM_SHORE_W;
                if (le) return is_ns_river ? (uint8_t)CM_SHORE_V_E : (uint8_t)CM_SHORE_E;
                if (lnw) return (uint8_t)CM_SHORE_INW;
                if (lne) return (uint8_t)CM_SHORE_INE;
                if (lsw) return (uint8_t)CM_SHORE_ISW;
                if (lse) return (uint8_t)CM_SHORE_ISE;
            }
        }
        if (!is_world && is_ns_river) {
            if (t == T_RAPIDS) return (uint8_t)CM_RAPIDS_V;
            if (t == T_WATER)  return (uint8_t)CM_WATER_V;
        }
        return t;
    }
    /* 4. Organic Rounded Sand/Beach-to-Grass Biome Transitions (World + Local Coastal Zones!) */
    if (t == T_WORLD_BEACH || t == T_WORLD_SAND) {
        uint8_t gn = hearth_is_grass_like(tn);
        uint8_t gs = hearth_is_grass_like(ts);
        uint8_t gw = hearth_is_grass_like(tw);
        uint8_t ge = hearth_is_grass_like(te);
        if (gn && gw) return (uint8_t)CM_SAND_GRASS_NW;
        if (gn && ge) return (uint8_t)CM_SAND_GRASS_NE;
        if (gs && gw) return (uint8_t)CM_SAND_GRASS_SW;
        if (gs && ge) return (uint8_t)CM_SAND_GRASS_SE;
        if (gn) return (uint8_t)CM_SAND_GRASS_N;
        if (gs) return (uint8_t)CM_SAND_GRASS_S;
        if (gw) return (uint8_t)CM_SAND_GRASS_W;
        if (ge) return (uint8_t)CM_SAND_GRASS_E;
        if (t == T_WORLD_SAND && (v & 1u)) return (uint8_t)CM_SAND_V1;
        return t;
    }
    /* 5. Cast Ground Shadows, Rounded Road Corners & Canopy Dapple */
    if (!is_world) {
        if (t == T_COBBLE) {
            uint8_t gn = hearth_is_grass_like(tn);
            uint8_t gs = hearth_is_grass_like(ts);
            uint8_t gw = hearth_is_grass_like(tw);
            uint8_t ge = hearth_is_grass_like(te);
            if (hearth_is_solid_caster(tn)) return (uint8_t)CM_COBBLE_SHAD_N;
            if (hearth_is_solid_caster(tw)) return (uint8_t)CM_COBBLE_SHAD_W;
            if (gn && gw) return (uint8_t)CM_COBBLE_CORNER_NW;
            if (gn && ge) return (uint8_t)CM_COBBLE_CORNER_NE;
            if (gs && gw) return (uint8_t)CM_COBBLE_CORNER_SW;
            if (gs && ge) return (uint8_t)CM_COBBLE_CORNER_SE;
            if (gn) return (uint8_t)CM_COBBLE_EDGE_N;
            if (gs) return (uint8_t)CM_COBBLE_EDGE_S;
            if (gw) return (uint8_t)CM_COBBLE_EDGE_W;
            if (ge) return (uint8_t)CM_COBBLE_EDGE_E;
            if (v == 1u) return (uint8_t)CM_COBBLE_V1;
            if (v == 2u) return (uint8_t)CM_COBBLE_V2;
            if (v == 3u) return (uint8_t)CM_COBBLE_V3;
            return T_COBBLE;
        }
        if (t == T_GRASS || t == T_GRASS_ALT) {
            if (hearth_is_solid_caster(tn)) return (uint8_t)CM_GRASS_SHAD_N;
            if (hearth_is_solid_caster(tw)) return (uint8_t)CM_GRASS_SHAD_W;
            if (ov != 0u) return (uint8_t)CM_GRASS_DAPPLE;
            if (v == 1u) return (uint8_t)CM_GRASS_V1;
            if (v == 2u) return (uint8_t)CM_GRASS_V2;
            if (v == 3u) return (uint8_t)CM_GRASS_V3;
            return T_GRASS;
        }
        if (t == T_AUTUMN_GRASS) {
            if (hearth_is_solid_caster(tn)) return (uint8_t)CM_AUTUMN_SHAD_N;
            if (ov != 0u) return (uint8_t)CM_AUTUMN_DAPPLE;
            if (v == 1u) return (uint8_t)CM_AUTUMN_V1;
            if (v == 2u) return (uint8_t)CM_AUTUMN_V2;
            return T_AUTUMN_GRASS;
        }
        if (t == T_DIRT) {
            uint8_t gn = hearth_is_grass_like(tn);
            uint8_t gs = hearth_is_grass_like(ts);
            uint8_t gw = hearth_is_grass_like(tw);
            uint8_t ge = hearth_is_grass_like(te);
            if (hearth_is_solid_caster(tn)) return (uint8_t)CM_DIRT_SHAD_N;
            if (gn && gw) return (uint8_t)CM_DIRT_CORNER_NW;
            if (gn && ge) return (uint8_t)CM_DIRT_CORNER_NE;
            if (gs && gw) return (uint8_t)CM_DIRT_CORNER_SW;
            if (gs && ge) return (uint8_t)CM_DIRT_CORNER_SE;
            if (gn) return (uint8_t)CM_DIRT_EDGE_N;
            if (gs) return (uint8_t)CM_DIRT_EDGE_S;
            if (gw) return (uint8_t)CM_DIRT_EDGE_W;
            if (ge) return (uint8_t)CM_DIRT_EDGE_E;
            return (v & 1u) ? (uint8_t)CM_DIRT_V1 : T_DIRT;
        }
        if (t == T_ROCKY_PATH) {
            uint8_t gn = hearth_is_grass_like(tn);
            uint8_t gs = hearth_is_grass_like(ts);
            uint8_t gw = hearth_is_grass_like(tw);
            uint8_t ge = hearth_is_grass_like(te);
            if (hearth_is_solid_caster(tn)) return (uint8_t)CM_ROCKY_SHAD_N;
            if (gn && gw) return (uint8_t)CM_COBBLE_CORNER_NW;
            if (gn && ge) return (uint8_t)CM_COBBLE_CORNER_NE;
            if (gs && gw) return (uint8_t)CM_COBBLE_CORNER_SW;
            if (gs && ge) return (uint8_t)CM_COBBLE_CORNER_SE;
            if (gn) return (uint8_t)CM_COBBLE_EDGE_N;
            if (gs) return (uint8_t)CM_COBBLE_EDGE_S;
            if (gw) return (uint8_t)CM_COBBLE_EDGE_W;
            if (ge) return (uint8_t)CM_COBBLE_EDGE_E;
            return (v & 1u) ? (uint8_t)CM_ROCKY_V1 : T_ROCKY_PATH;
        }
        if (t == T_WOOD_FLOOR) {
            if (hearth_is_solid_caster(tn)) return (uint8_t)CM_WOOD_SHAD_N;
            return (v & 1u) ? (uint8_t)CM_WOOD_FLOOR_V1 : T_WOOD_FLOOR;
        }
        if (t == T_SHRINE_FLOOR && (v & 1u)) return (uint8_t)CM_SHRINE_V1;
    } else {
        /* World Map spatial variation */
        if (t == T_GRASS && v > 0u) return (uint8_t)(CM_GRASS_V1 + (v - 1u));
        if (t == T_WORLD_SNOW && (v & 1u)) return (uint8_t)CM_SNOW_V1;
        if (t == T_WORLD_JUNGLE && (v & 1u)) return (uint8_t)CM_JUNGLE_V1;
    }
    return (t < 63u) ? t : (uint8_t)T_GRASS;
}

